import{_ as e,o as t,c as s,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const k=JSON.parse('{"title":"逻辑时钟、向量时钟、HLC","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/clock/logical.md","filePath":"distributed/clock/logical.md","lastUpdated":1788475713000}'),n={name:"distributed/clock/logical.md"};function o(l,a,r,c,d,p){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="逻辑时钟、向量时钟、hlc" tabindex="-1">逻辑时钟、向量时钟、HLC <a class="header-anchor" href="#逻辑时钟、向量时钟、hlc" aria-label="Permalink to &quot;逻辑时钟、向量时钟、HLC&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>分布式系统<strong>无全局 wall clock</strong>——你不能用一个普通的 timestamp 来判定两事件先后。Lamport 1978 提出 <strong>Lamport Clock</strong>: 每节点维护单调自增 count, message 携带 count → 接收方更新成 max(local, msg_count)+1, 给事件一个<strong>全序但仅保因果 partial order</strong> 后将并发事件任意排序。Fidge 1988 与 Mattern 1989 各自独立发现 <strong>Vector Clock</strong>: N 节点维 N 维 count array 在节点间传播, 精确刻画 <code>happens-before</code>, 区分 concurrent vs causal-ordered pair。<strong>HLC (Hybrid Logical Clock, Kulkarni 2014)</strong> 融合 physical wall clock 的高位 + logical counter 低位, 给事件同时<strong>人友好的时间戳 + 因果关系</strong> —— CockroachDB / YugaByte / TiDB 都用 HLC 做事务 timestamp。本章梳理算法细节, 收敛条件, 用例 (Dynamo siblings, CockroachDB snapshot isolation), 与 typical bug (Lamport clock 单调 但并发 events 任意序 不区分)。</p><hr><h2 id="一、lamport-clock-1978" tabindex="-1">一、Lamport Clock (1978) <a class="header-anchor" href="#一、lamport-clock-1978" aria-label="Permalink to &quot;一、Lamport Clock (1978)&quot;">​</a></h2><h3 id="算法" tabindex="-1">算法 <a class="header-anchor" href="#算法" aria-label="Permalink to &quot;算法&quot;">​</a></h3><p>每节点维护 monotonic counter <code>LC_i</code>, 初始 0:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>on event e at node i (send / receive / local): LC_i = LC_i + 1</span></span>
<span class="line"><span>on send(m): attach LC_i to m</span></span>
<span class="line"><span>on receive(m, LC_m): LC_i = max(LC_i, LC_m) + 1</span></span></code></pre></div><h3 id="性质" tabindex="-1">性质 <a class="header-anchor" href="#性质" aria-label="Permalink to &quot;性质&quot;">​</a></h3><ul><li><strong>happens-before</strong>: 若 <code>a → b</code> (同进程序 + send/recv + 传递闭包), 则 <code>LC(a) &lt; LC(b)</code>。</li><li><strong>逆否命题不成立</strong>: <code>LC(a) &lt; LC(b)</code> 不蕴含 <code>a → b</code>——它们可能 concurrent。</li><li><strong>全序扩展</strong>: 把 Lamport Clock + (process_id) lex 排, 得到 total order (任两个事件都可比), 但这是任意扩展, 不是 happens-before 原 partial order 的忠实反映。</li></ul><h3 id="用例" tabindex="-1">用例 <a class="header-anchor" href="#用例" aria-label="Permalink to &quot;用例&quot;">​</a></h3><ul><li><strong>Mutual Exclusion via Lamport Clock</strong>: Lamport 1978 论文里给出 distributed mutex 算法, 提议临界区请求带 LC + process_id, 节点色 total order 排队。O(N²) messages, 严谨 but 低效; 不工业用 (因 Paxos/Raft 都更高效更好)。</li><li><strong>DynamoDB (AWS) Order Stream</strong>: DynamoDB change stream 用 LC-style 时间戳排序 events 在 短时间窗内。</li></ul><h3 id="局限" tabindex="-1">局限 <a class="header-anchor" href="#局限" aria-label="Permalink to &quot;局限&quot;">​</a></h3><p>Lamport Clock <strong>不能</strong> 区分因果序与并发序:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A: send m_A (LC_A=5)</span></span>
<span class="line"><span>B: send m_B (LC_B=5)        concurrent with A</span></span></code></pre></div><p>两 event LC 相同, 看上去&quot;同时间发生&quot;; 真实它们 concurrent (不是 causally related)。</p><p>vector clock 解决这 limit。</p><hr><h2 id="二、vector-clock-fidge-1988-mattern-1989" tabindex="-1">二、Vector Clock (Fidge 1988, Mattern 1989) <a class="header-anchor" href="#二、vector-clock-fidge-1988-mattern-1989" aria-label="Permalink to &quot;二、Vector Clock (Fidge 1988, Mattern 1989)&quot;">​</a></h2><h3 id="算法-1" tabindex="-1">算法 <a class="header-anchor" href="#算法-1" aria-label="Permalink to &quot;算法&quot;">​</a></h3><p>每节点 i 维护 N 维 vector <code>VC_i = (c_0, c_1, ..., c_{N-1})</code>, 初始全 0:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>on local event at i: VC_i[i] += 1</span></span>
<span class="line"><span>on send(m) at i: VC_i[i] += 1; attach VC_i to m</span></span>
<span class="line"><span>on receive(m, VC_m) at i:</span></span>
<span class="line"><span>    for all j: VC_i[j] = max(VC_i[j], VC_m[j])</span></span>
<span class="line"><span>    VC_i[i] += 1</span></span></code></pre></div><h3 id="关系比较" tabindex="-1">关系比较 <a class="header-anchor" href="#关系比较" aria-label="Permalink to &quot;关系比较&quot;">​</a></h3><p><code>VC_a ≤ VC_b</code> iff <code>∀ k: VC_a[k] ≤ VC_b[k]</code><code>VC_a &lt; VC_b</code> iff <code>VC_a ≤ VC_b ∧ ∃ k: VC_a[k] &lt; VC_b[k]</code></p><ul><li><code>VC_a &lt; VC_b</code> ⟹ <code>a → b</code> (happens-before)</li><li><code>VC_a || VC_b</code> (即不 ≤ 也不 ≥) ⟹ <code>a</code> 与 <code>b</code> concurrent</li></ul><h3 id="用例-1" tabindex="-1">用例 <a class="header-anchor" href="#用例-1" aria-label="Permalink to &quot;用例&quot;">​</a></h3><p><strong>Dynamo / Riak siblings</strong>: writes 带 VC, replica merge 给出 vector clock 比较:</p><ul><li>若 <code>VC_a &lt; VC_b</code> → discard <code>a</code> (newer overrides)</li><li>若 <code>VC_a || VC_b</code> → 两个都保留为 sibling, 应用层 merge</li></ul><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> merge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(replica_a_value, replica_b_value, VC_a, VC_b):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> VC_a</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> VC_b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> replica_b_value, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">VC_b</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    elif</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> VC_b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> VC_a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> replica_a_value, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">VC_a</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # siblings; 应用层 merge function (or list all)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [replica_a_value, replica_b_value], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">VC_a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">VC_b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="vector-clock-变种" tabindex="-1">Vector Clock 变种 <a class="header-anchor" href="#vector-clock-变种" aria-label="Permalink to &quot;Vector Clock 变种&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变种</th><th>区别</th></tr></thead><tbody><tr><td><strong>Version Vector (VV)</strong></td><td>仅 update on write, 不 update on read; Dynamo 用 VV。简单但 N 写 parties 固定。</td></tr><tr><td><strong>Dotted Version Vector (DVV)</strong></td><td>引入 &quot;dot&quot; = (node_id, counter) 唯一标识一次 occurrence. 应用 client cluster anonymity (单 client 同 node)。 Riak 用。</td></tr><tr><td><strong>Interval Version Vector (IVV)</strong></td><td>counter 改成 interval [start, end], 处理 dynamic membership, 节点 join/leave 不 reset。</td></tr><tr><td><strong>DCVV (Dotted Cluster VV)</strong></td><td>DVV + cluster id, 高度 dynamic membership (Cassandra 内部曾用)。</td></tr></tbody></table><h3 id="vector-clock-内存代价" tabindex="-1">Vector Clock 内存代价 <a class="header-anchor" href="#vector-clock-内存代价" aria-label="Permalink to &quot;Vector Clock 内存代价&quot;">​</a></h3><p>每 message 维传 N 维整数, O(N) per event; Cassandra / Riak 在 N=100 nodes 情况 VC serialize ~1KB 包过载。常见优化 <strong>Dotted VV</strong> + compact representation.</p><h3 id="局限-1" tabindex="-1">局限 <a class="header-anchor" href="#局限-1" aria-label="Permalink to &quot;局限&quot;">​</a></h3><p>Vector clock <strong>检测</strong> concurrency 但<strong>不解决</strong>conflict——应用层仍需 merge function. Riak DT (CRDT) 与 Riak siblings 都让 application 决定逻辑, vector clock 只是 procedure infrastructure.</p><hr><h2 id="三、hlc-hybrid-logical-clock-kulkarni-2014" tabindex="-1">三、HLC (Hybrid Logical Clock, Kulkarni 2014) <a class="header-anchor" href="#三、hlc-hybrid-logical-clock-kulkarni-2014" aria-label="Permalink to &quot;三、HLC (Hybrid Logical Clock, Kulkarni 2014)&quot;">​</a></h2><h3 id="动机" tabindex="-1">动机 <a class="header-anchor" href="#动机" aria-label="Permalink to &quot;动机&quot;">​</a></h3><p>Pure logical clock 与人读时间无关 (&quot;这 event 是 timestamp 1000, 但何时真实发生&quot;)；pure wall clock 受 NTP skew 影响 + 不保 happens-before。 HLC 融合:</p><ul><li>高位 = wall clock 时间 (<code>pt</code>)</li><li>低位 = 逻辑 counter (<code>lt</code>)</li><li>(pt, lt) 元组保证 causal happens-before + timestamp 接近 wall clock 真实发生时刻</li></ul><h3 id="算法-2" tabindex="-1">算法 <a class="header-anchor" href="#算法-2" aria-label="Permalink to &quot;算法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>each node init HLC = (wall_now, 0)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on local event at node i:</span></span>
<span class="line"><span>    if wall_now &gt; HLC.pt:</span></span>
<span class="line"><span>        HLC = (wall_now, 0)</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        HLC = (HLC.pt, HLC.lt + 1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on send(m):</span></span>
<span class="line"><span>    bump HLC (above); attach HLC to m</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on receive(m, HLC_m):</span></span>
<span class="line"><span>    new_pt = max(wall_now, HLC.pt, HLC_m.pt)</span></span>
<span class="line"><span>    if new_pt == HLC.pt == HLC_m.pt:</span></span>
<span class="line"><span>        HLC = (new_pt, max(HLC.lt, HLC_m.lt) + 1)</span></span>
<span class="line"><span>    elif new_pt == HLC.pt:</span></span>
<span class="line"><span>        HLC = (new_pt, HLC.lt + 1)</span></span>
<span class="line"><span>    elif new_pt == HLC_m.pt:</span></span>
<span class="line"><span>        HLC = (new_pt, HLC_m.lt + 1)</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        HLC = (new_pt, 0)</span></span></code></pre></div><h3 id="性质-1" tabindex="-1">性质 <a class="header-anchor" href="#性质-1" aria-label="Permalink to &quot;性质&quot;">​</a></h3><ul><li><code>a → b</code> ⟹ <code>HLC(a) &lt; HLC(b)</code> (lex by pt then lt)</li><li><code>HLC(a) &lt; HLC(b)</code> ⟹ <code>a → b</code> (no false positives because counter monotonic)</li><li>pt 接近真实 wall clock, 人读 HLC 时知道大致真实发生时刻</li></ul><h3 id="用例-2" tabindex="-1">用例 <a class="header-anchor" href="#用例-2" aria-label="Permalink to &quot;用例&quot;">​</a></h3><p><strong>CockroachDB HLC</strong>:</p><ul><li>每 transaction 用 HLC timestamp。</li><li>HLC 与 wall clock bound skew (max_offset 默认 250ms) → 同物理事件可 timestamp 偏移 &lt; 250ms +1 logical tick.</li><li>transaction read 是 snapshot isolation at HLC timestamp; 查 commit HLC &gt; read HLC 排除 commit-on-after-read 的 row.</li></ul><p><strong>YugaByte / TiDB</strong> 与 CockroachDB 类似, 内置 HLC + bounded skew.</p><p><strong>MongoDB</strong>: 但 MongoDB 没用 HLC, 用 wall clock + reverse_sbe seq for global timestamp cluster clock.</p><h3 id="bounded-skew" tabindex="-1">Bounded skew <a class="header-anchor" href="#bounded-skew" aria-label="Permalink to &quot;Bounded skew&quot;">​</a></h3><p>HLC 让各节点 wall_now <strong>bounded</strong> skew (默认 250ms in CockroachDB), 通过 max_offset 配置后 cluster know if wall clock drift &gt; max_offset → 节点必须 fail exit.</p><p>否则 HLC 不保 happens-before—— wall clock 直跳, counter 才保证.</p><hr><h2 id="四、hlc-vs-truetime" tabindex="-1">四、HLC vs TrueTime <a class="header-anchor" href="#四、hlc-vs-truetime" aria-label="Permalink to &quot;四、HLC vs TrueTime&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>HLC (CockroachDB)</th><th>TrueTime (Spanner)</th></tr></thead><tbody><tr><td>同步精度</td><td>bounded skew ~250ms (NTP)</td><td>bounded skew ~7ms (GPS + 原子钟)</td></tr><tr><td>Commit-style wait</td><td>不必 wait</td><td>commit-wait (wait until TT.now() latest &gt; commit_ts)</td></tr><tr><td>软实时?</td><td>PT-approx not real-time</td><td>cl实事实时 (commit-wait ~14ms)</td></tr><tr><td>Garbage-in short window?</td><td>≤ max_offset</td><td>commit-waitカバー</td></tr><tr><td>实现复杂度</td><td>适中</td><td>expensive (timing hardware per datacenter)</td></tr></tbody></table><p>HLC 比 TrueTime 简单 (NTP 普及) 但 commit wait 长 (250ms worst case 把 commit fully serialized across events). TrueTime 直接 GPS 持 7ms skew → commit wait 14ms。</p><hr><h2 id="五、生产事故" tabindex="-1">五、生产事故 <a class="header-anchor" href="#五、生产事故" aria-label="Permalink to &quot;五、生产事故&quot;">​</a></h2><h3 id="riak-vector-clock-sibling-风暴" tabindex="-1">Riak Vector Clock Sibling 风暴 <a class="header-anchor" href="#riak-vector-clock-sibling-风暴" aria-label="Permalink to &quot;Riak Vector Clock Sibling 风暴&quot;">​</a></h3><p>Riak 2.0 一度 1995 严格 VC 让 client 看 sibling list; but application 不设 merge fn → sibling list 中 5 个 values; 用户不 that 失潘 krebs写 fail 加 format. Fix: Riak DT (CRDTs) let user set bucket type data_type = counter/set/map, 默认让 Riak 内置 merge logic.</p><h3 id="cassandra-lww-skew-lost-write" tabindex="-1">Cassandra LWW + Skew Lost Write <a class="header-anchor" href="#cassandra-lww-skew-lost-write" aria-label="Permalink to &quot;Cassandra LWW + Skew Lost Write&quot;">​</a></h3><p>Cassandra 单一 timestamp 驱动 LWW。某写入 client NTP skew 5 秒晚, 其 timestamp 偏大 → 后写 user 可能有 της late timestamp &gt; 中先existent。后写 overwrite 不合法 drifted NTP data wrote системы. Fix: 用 client_id + monotonic timestamp 而非 now(); 是Cassandra Java driver 自带。</p><h3 id="cockroachdb-hlc-偏离-→-out-of-order-read" tabindex="-1">CockroachDB HLC 偏离 → Out-of-Order Read <a class="header-anchor" href="#cockroachdb-hlc-偏离-→-out-of-order-read" aria-label="Permalink to &quot;CockroachDB HLC 偏离 → Out-of-Order Read&quot;">​</a></h3><p>CockroachDB HLC 假设 max_offset = 250ms。 某节点 NTP drift 超过 250ms 后, write ts 偏移 too far &gt; 其他节点会读到 stale committed 数据. Fix: cluster 启动 + 周期 monitor NTP divergence, 超过 251ms 让节点自行 fail exit.</p><hr><h2 id="六、易错清单" tabindex="-1">六、易错清单 <a class="header-anchor" href="#六、易错清单" aria-label="Permalink to &quot;六、易错清单&quot;">​</a></h2><ol><li><strong>Lamport Clock 不能区分并发</strong>: LC(a) &lt; LC(b) 不能推 a → b, 因为 a 和 b 可能 concurrent. 要并发检测必用 Vector Clock。</li><li><strong>Vector Clock 不解决 conflict, 仅 detect它</strong>: 应用层 merge function 必须好好设, 否则 sibling 无限堆积.</li><li><strong>Vector Clock 必须传整个 vector 而非只是 last counter</strong>: 传 dot 而非 vector 就 lost causal info ⇒ DVV 设计 fixing 此。</li><li><strong>HLC 不有 external consistency</strong>: HLC 假设 bounded skew, commit-wait 时达不到线性化世界的&quot;real-time 一致&quot;—— 上 bounded skew = 250ms CockroachDB commit-wait 不需 wait 直接发 ts, 因此 client 可能在 read 看到 future ts commit。 CockroachDB explicit <code>read_no_write_ahead</code> 处理。</li><li><strong>HLC <code>max_offset</code> 必须 monitor</strong>: NTP drift 大会让 HLC invalid. cluster health dashboard 必须显示 skew。</li><li><strong>Wall clock not monotonic</strong>: 重启或 NTP step 后 wall clock 可能跳 backwards. HLC 算法中 <code>if wall_now &gt; HLC.pt</code> 检查保护, 但 NTP <strong>stepping</strong> 总需要 long-term installreboot aware.</li><li><strong>Vector Clock encoding 没用 delta compaction</strong>: 100 node VC 数组大. 工业用 sparse + delta encoding (如果 4 节 domany-HashMap gas has compile 快).</li></ol><hr><h2 id="七、这一章带走的东西" tabindex="-1">七、这一章带走的东西 <a class="header-anchor" href="#七、这一章带走的东西" aria-label="Permalink to &quot;七、这一章带走的东西&quot;">​</a></h2><ol><li>Lamport Clock 给 happens-before <strong>保 inter-process ordering</strong> 但不区分并发; vector clock 精确刻画并发但 N node cost.</li><li>Vector Clock 在 Dynamo / Riak siblings 上 detect concurrent writes, application merge function 解决 conflict.</li><li>HLC 融合 wall clock + logical counter, 给人友好的时间戳同时保 happens-before. CockroachDB / YugaByte / TiDB 内置。</li><li>TrueTime (Spanner) 通过 GPS+ atomic clock 直接给 7ms 内 skew, commit-wait 实现 external consistency。 与 HLC API 形式 似但 hardware 差异大。</li><li>Vector Clock vs Version Vector vs Dotted Version Vector vs Interval Version Vector 是 distributed stores 世代演进, 处理 client anonymity + dynamic membership。</li><li>Lamport Clock Total Order (LC + process_id) 是任意 tie-break; 不能用来推并发 events simultaneous.</li></ol><hr><p>下一节 → <a href="./physical">TrueTime / HLC / attestation</a></p>`,72)])])}const m=e(n,[["render",o]]);export{k as __pageData,m as default};
